    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'speak',17,NULL,NULL,'در موقعیتی تازه، بله، کیف اینجاست. را با یک بیان مناسب بگو.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"در موقعیتی تازه، بله، کیف اینجاست. را با یک بیان مناسب بگو.","scenario_fa":"در موقعیتی تازه، بله، کیف اینجاست. را با یک بیان مناسب بگو.","accepted":["Ja, die Tasche ist hier.","Ja, ich habe die Tasche.","Die Tasche ist bei mir."],"acceptedIntents":["Ja, die Tasche ist hier.","Ja, ich habe die Tasche.","Die Tasche ist bei mir."],"accepted_intents":["Ja, die Tasche ist hier.","Ja, ich habe die Tasche.","Die Tasche ist bei mir."],"input":"speech","audioRequired":false,"textVisible":false,"scored":true,"independent":true,"masteryCheck":true,"cumulativeMastery":true}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',4));
    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'speak',18,NULL,NULL,'در گفت‌وگویی تازه، با کمال میل، اما اول نشانی. را بدون دیدن متن آلمانی بیان کن.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"در گفت‌وگویی تازه، با کمال میل، اما اول نشانی. را بدون دیدن متن آلمانی بیان کن.","scenario_fa":"در گفت‌وگویی تازه، با کمال میل، اما اول نشانی. را بدون دیدن متن آلمانی بیان کن.","accepted":["Gern, aber zuerst die Adresse.","Ja, zuerst prüfen wir die Adresse.","Gern, die Adresse zuerst."],"acceptedIntents":["Gern, aber zuerst die Adresse.","Ja, zuerst prüfen wir die Adresse.","Gern, die Adresse zuerst."],"accepted_intents":["Gern, aber zuerst die Adresse.","Ja, zuerst prüfen wir die Adresse.","Gern, die Adresse zuerst."],"input":"speech","audioRequired":false,"textVisible":false,"scored":true,"independent":true,"masteryCheck":true,"cumulativeMastery":true}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',4));
  ELSEIF v_count=1 THEN
    IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 OR (SELECT COUNT(*) FROM turns t JOIN lessons l ON l.id=t.lesson_id WHERE l.chapter_id=v_chapter)<>50 OR (SELECT COUNT(*) FROM activities a JOIN lessons l ON l.id=a.lesson_id WHERE l.chapter_id=v_chapter)<>72 OR JSON_UNQUOTE(JSON_EXTRACT((SELECT metadata FROM chapters WHERE id=v_chapter),'$.stageId'))<>'de-fa-a1-series-0004' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Existing chapter does not match the validated stage'; END IF;
  ELSE SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter identity is not unique'; END IF;
  IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter must contain exactly four lessons'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN turns t ON t.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(t.id)<8 OR COUNT(t.id)>14) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Turn quota failed'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN activities a ON a.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(a.id)<>18) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Activity quota failed'; END IF;
  COMMIT;
END$$
